import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateField } from '../redux/formSlice';

export default function StepThree({ prev }) {
  const dispatch = useDispatch();
  const { dob, gender, confirm } = useSelector(state => state.form);

  return (
    <>
      <h4>Step 3: Final Details</h4>
      <input type="date" className="form-control my-2" value={dob}
        onChange={e => dispatch(updateField({ field: 'dob', value: e.target.value }))} />

      <div className="my-2">
        <label className="me-3">
          <input type="radio" name="gender" value="Male" checked={gender === 'Male'}
            onChange={e => dispatch(updateField({ field: 'gender', value: e.target.value }))} /> Male
        </label>
        <label>
          <input type="radio" name="gender" value="Female" checked={gender === 'Female'}
            onChange={e => dispatch(updateField({ field: 'gender', value: e.target.value }))} /> Female
        </label>
      </div>

      <div className="form-check my-2">
        <input type="checkbox" className="form-check-input" checked={confirm}
          onChange={e => dispatch(updateField({ field: 'confirm', value: e.target.checked }))} />
        <label className="form-check-label">I confirm my details</label>
      </div>

      <div className="d-flex justify-content-between mt-3">
        <button className="btn btn-secondary" onClick={prev}>← Prev</button>
        <button className="btn btn-success" disabled={!confirm}>Submit</button>
      </div>
    </>
  );
}
